# eco115: thang giá đều hơn; lợp mái, sửa nhà đòi đúng vật liệu và bữa đãi xóm; việc cấp 13, 14, 16, 17 ăn nhập với cái được mở. python3 eco115.py vào ra
import sys,re
src,dst=sys.argv[1],sys.argv[2]; s=open(src,encoding='utf-8').read()
def rep(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:70],s.count(a))
    s=s.replace(a,b)
def objp(k,old,new):
    global s
    pat=re.compile(r"(\b"+k+r": \{ name: '[^']+',[^}]*?lv: \d+, buy: )"+str(old)+r"\b")
    s,n=pat.subn(lambda m:m.group(1)+str(new),s,count=1); assert n==1,k
